interface Coffee {
    String getDescription();
    double getCost();
}

record SimpleCoffee() implements Coffee {
    public String getDescription() { return "Simple coffee"; }
    public double getCost() { return 2.0; }
}

abstract class CoffeeDecorator implements Coffee {
    protected final Coffee wrapped;  // holds the wrapped component
    CoffeeDecorator(Coffee coffee) { this.wrapped = coffee; }
}

class MilkDecorator extends CoffeeDecorator {
    MilkDecorator(Coffee coffee) { super(coffee); }
    public String getDescription() { return wrapped.getDescription() + ", milk"; }
    public double getCost() { return wrapped.getCost() + 0.5; }  // adds milk cost
}

class SugarDecorator extends CoffeeDecorator {
    SugarDecorator(Coffee coffee) { super(coffee); }
    public String getDescription() { return wrapped.getDescription() + ", sugar"; }
    public double getCost() { return wrapped.getCost() + 0.2; }
}

// Usage: wrap dynamically at runtime
var coffee = new SimpleCoffee();
var milkCoffee = new MilkDecorator(coffee);
var milkSugarCoffee = new SugarDecorator(milkCoffee);  // nested wrapping
System.out.println(milkSugarCoffee.getDescription() + " = $" + milkSugarCoffee.getCost());

import java.io.*;
import java.util.zip.GZIPInputStream;

public class StreamDecoratorExample {
    public static void main(String[] args) throws IOException {
        var file = new File("data.txt.gz");

        // Component: FileInputStream reads raw bytes from disk
        InputStream fileStream = new FileInputStream(file);

        // Decorator 1: GZIPInputStream adds decompression
        InputStream gzipStream = new GZIPInputStream(fileStream);

        // Decorator 2: BufferedInputStream adds buffering for performance
        InputStream bufferedStream = new BufferedInputStream(gzipStream);

        // Decorator 3: DataInputStream adds typed reading methods
        DataInputStream dataStream = new DataInputStream(bufferedStream);

        // Usage: each decorator transparently wraps the previous layer
        int value = dataStream.readInt();  // reads int from buffered, decompressed file
        System.out.println("Read value: " + value);

        dataStream.close();  // closes entire chain
    }
}

interface OrderService {
    Order findById(Long id);
    void save(Order order);
}

class OrderServiceImpl implements OrderService {
    public Order findById(Long id) { /* business logic */ return new Order(id, "item"); }
    public void save(Order order) { /* business logic */ }
}

class LoggingOrderService implements OrderService {
    private final OrderService wrapped;
    LoggingOrderService(OrderService service) { this.wrapped = service; }

    public Order findById(Long id) {
        System.out.println("[LOG] findById called with id=" + id);  // logging before
        var result = wrapped.findById(id);  // delegate to real service
        System.out.println("[LOG] findById returned: " + result);  // logging after
        return result;
    }
    public void save(Order order) { wrapped.save(order); }  // delegate-only for brevity
}

class CachingOrderService implements OrderService {
    private final OrderService wrapped;
    private final Map<Long, Order> cache = new HashMap<>();
    CachingOrderService(OrderService service) { this.wrapped = service; }

    public Order findById(Long id) {
        return cache.computeIfAbsent(id, wrapped::findById);  // cache or delegate
    }
    public void save(Order order) { wrapped.save(order); }
}

// Usage: stack decorators at runtime
OrderService service = new OrderServiceImpl();
service = new CachingOrderService(service);  // add caching
service = new LoggingOrderService(service);  // add logging on top

interface MessageService {
    void send(String message);
}

class EmailService implements MessageService {
    public void send(String message) {
        System.out.println("Sending email: " + message);  // base behavior
    }
}

abstract class MessageServiceDecorator implements MessageService {
    protected final MessageService wrapped;  // holds the wrapped component
    MessageServiceDecorator(MessageService service) { this.wrapped = service; }
    public void send(String message) { wrapped.send(message); }  // default delegation
}

class EncryptionDecorator extends MessageServiceDecorator {
    EncryptionDecorator(MessageService service) { super(service); }
    public void send(String message) {
        var encrypted = "[ENCRYPTED]" + message;  // add behavior before
        wrapped.send(encrypted);  // delegate to wrapped
    }
}

class LoggingDecorator extends MessageServiceDecorator {
    LoggingDecorator(MessageService service) { super(service); }
    public void send(String message) {
        System.out.println("[LOG] Sending message: " + message);  // add behavior before
        wrapped.send(message);  // delegate
        System.out.println("[LOG] Message sent");  // add behavior after
    }
}

// Usage: wrap decorators at runtime
MessageService service = new EmailService();
service = new EncryptionDecorator(service);  // wrap with encryption
service = new LoggingDecorator(service);  // wrap with logging
service.send("Hello");  // triggers logging -> encryption -> email

interface UserRepository {
    Optional<User> findById(Long id);
    void save(User user);
}

class JpaUserRepository implements UserRepository {
    public Optional<User> findById(Long id) {
        // actual database query via JPA
        System.out.println("[DB] Querying user with id=" + id);
        return Optional.of(new User(id, "Alice"));
    }
    public void save(User user) { /* insert or update */ }
}

class CachingUserRepository implements UserRepository {
    private final UserRepository wrapped;  // holds the real repository
    private final Map<Long, User> cache = new ConcurrentHashMap<>();  // thread-safe cache

    CachingUserRepository(UserRepository repository) { this.wrapped = repository; }

    public Optional<User> findById(Long id) {
        if (cache.containsKey(id)) {  // check cache first
            System.out.println("[CACHE] Hit for id=" + id);
            return Optional.of(cache.get(id));
        }
        System.out.println("[CACHE] Miss for id=" + id);
        var user = wrapped.findById(id);  // delegate to real repository
        user.ifPresent(u -> cache.put(id, u));  // store in cache
        return user;
    }

    public void save(User user) {
        wrapped.save(user);
        cache.put(user.id(), user);  // update cache on save
    }
}

// Usage: wrap repository with caching
UserRepository repo = new JpaUserRepository();
repo = new CachingUserRepository(repo);
repo.findById(1L);  // DB query
repo.findById(1L);  // cache hit

interface PaymentProcessor {  // component interface — shared contract
    void processPayment(double amount);
}

class StripePaymentProcessor implements PaymentProcessor {
    public void processPayment(double amount) {
        System.out.println("Processing $" + amount + " via Stripe");
    }
}

class PayPalPaymentProcessor implements PaymentProcessor {
    public void processPayment(double amount) {
        System.out.println("Processing $" + amount + " via PayPal");
    }
}

abstract class PaymentProcessorDecorator implements PaymentProcessor {  // decorators implement same interface
    protected final PaymentProcessor wrapped;
    PaymentProcessorDecorator(PaymentProcessor processor) { this.wrapped = processor; }
}

class LoggingPaymentDecorator extends PaymentProcessorDecorator {
    LoggingPaymentDecorator(PaymentProcessor processor) { super(processor); }
    public void processPayment(double amount) {
        System.out.println("[LOG] Payment of $" + amount + " initiated");
        wrapped.processPayment(amount);  // delegates to any PaymentProcessor
        System.out.println("[LOG] Payment completed");
    }
}

// Usage: decorator works with any implementation
PaymentProcessor stripe = new StripePaymentProcessor();
PaymentProcessor paypal = new PayPalPaymentProcessor();
PaymentProcessor loggedStripe = new LoggingPaymentDecorator(stripe);  // wraps Stripe
PaymentProcessor loggedPayPal = new LoggingPaymentDecorator(paypal);  // wraps PayPal
loggedStripe.processPayment(100.0);  // client sees only PaymentProcessor interface
